sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {

    // Construct a GlideRecord query to find all NeedIt Task records with Due date
    // field values in the past for the same Assigned to.  The records cannot be in the
    // Closed state.
    var rightNow = new GlideDateTime();

    var overdueNI = new GlideRecord('x_58872_needit_needit');
    overdueNI.addQuery('when_needed', '<=', rightNow);
    //overdueNITasks.addQuery('state', '<', 3);
    overdueNI.addQuery('requested_for', current.requested_for);

    overdueNI.query();

    // Print to the Message field on a notification 
    template.print("In addition to this overdue NeedIt, you have " + (overdueNI.getRowCount() - 1) + " more overdue NeedIt.");
})(current, template, email, email_action, event);
